/**
 * Personal API token rows. Rows are only ever handed out as `ApiToken`, so the
 * stored hash stays inside this module.
 *
 * Must call (do not reimplement): orgPredicate
 */
import { and, count, desc, eq, gt, isNull, sql } from "drizzle-orm";
import { apiTokens, getDb, type NewApiTokenRow } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toApiToken } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { ApiToken } from "@/types/api-token";

/**
 * Inserts a token unless its owner already holds `limit` usable tokens in the
 * org. The count and the insert share one synchronous SQLite transaction, so
 * two concurrent creates cannot both pass the check.
 */
export async function insertApiTokenWithinLimit(
  row: NewApiTokenRow & { orgId: OrgId; userId: UserId },
  limit: number,
  now: IsoTimestamp,
): Promise<ApiToken | null> {
  return getDb().transaction((tx) => {
    const usable = tx
      .select({ value: count() })
      .from(apiTokens)
      .where(
        and(
          orgPredicate(apiTokens.orgId, row.orgId),
          eq(apiTokens.userId, row.userId),
          isNull(apiTokens.revokedAt),
          gt(apiTokens.expiresAt, now),
        ),
      )
      .get();

    if ((usable?.value ?? 0) >= limit) return null;

    return toApiToken(tx.insert(apiTokens).values(row).returning().get());
  });
}

export async function findApiTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

/**
 * Resolves a presented secret. Deliberately not scoped to an org: the token
 * itself names its organization, and the caller checks that next.
 */
export async function findApiTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? toApiToken(row) : null;
}

/** Every token the user holds in the org, revoked and expired included. */
export async function listApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
      ),
    )
    .orderBy(desc(apiTokens.createdAt), sql`rowid desc`)
    .all();
  return rows.map(toApiToken);
}

/** Tokens the user holds in the org that have not been revoked yet. */
export async function listUnrevokedApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .all();
  return rows.map(toApiToken);
}

/**
 * Stamps `revokedAt` on a token that is not yet revoked. Returns `null` when
 * there was nothing to revoke, so the caller can tell a first revoke from a
 * repeat.
 */
export async function revokeApiTokenIfActive(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<ApiToken | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .get();
  return row ? toApiToken(row) : null;
}

export async function touchApiTokenLastUsed(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(apiTokens)
    .set({ lastUsedAt: at })
    .where(
      and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)),
    )
    .run();
}

