import { toIsoTimestamp } from "@/types/common";
import { actorEnvelope, apiTokenResource, envelope, requireFound } from "./_support";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

/** Every secret starts with this, so a leaked one is recognisable in a scan. */
const SECRET_PREFIX = "tfk_";

/** Random bytes behind the secret; 32 bytes encode to 43 URL-safe characters. */
const SECRET_BYTES = 32;

/** Characters of the secret kept as the display `prefix`. */
const PREFIX_LENGTH = 12;

/** Usable (unrevoked, unexpired) tokens one user may hold per organization. */
const MAX_USABLE_TOKENS = 5;

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * Mints a token. The secret exists only in the return value: the database
 * keeps its SHA-256, so a lost secret cannot be shown again, only replaced.
 */
export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);
  assertCan(actor, "api_token:create", apiTokenResource(parsed.orgId, actor.userId, null));
  if (parsed.scope === "write") {
    assertCan(
      actor,
      "api_token:create_write",
      apiTokenResource(parsed.orgId, actor.userId, null),
    );
  }

  const token = `${SECRET_PREFIX}${randomToken(SECRET_BYTES)}`;
  const now = new Date();
  const createdAt = toIsoTimestamp(now);

  const apiToken = await apiTokenRepo.insertApiTokenWithinLimit(
    {
      id: newId(),
      orgId: parsed.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      tokenHash: hashToken(token),
      prefix: token.slice(0, PREFIX_LENGTH),
      expiresAt: toIsoTimestamp(
        new Date(now.getTime() + parsed.expiresInDays * MS_PER_DAY),
      ),
      lastUsedAt: null,
      revokedAt: null,
      createdAt,
      updatedAt: createdAt,
    },
    MAX_USABLE_TOKENS,
    createdAt,
  );

  if (apiToken === null) {
    throw new Error(
      `You can hold at most ${MAX_USABLE_TOKENS} usable API tokens per organization; revoke or let one expire first`,
    );
  }

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

/**
 * Lists one user's tokens in the org, newest first, including revoked and
 * expired ones. Without `userId` it is the actor's own list; anyone else's
 * list needs `admin` or above.
 */
export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId?: UserId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  const owner = userId ?? actor.userId;
  assertCan(actor, "api_token:list", apiTokenResource(orgId, owner, null));
  return apiTokenRepo.listApiTokensForUser(orgId, owner);
}

/**
 * Revokes a token. Owners may always revoke their own; anyone else needs
 * `admin` or above. Revoking a token that is already revoked returns it as it
 * was stored, with its original `revokedAt`, and records nothing.
 */
export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);
  const existing = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );
  assertCan(actor, "api_token:revoke", apiTokenResource(orgId, existing.userId, existing.id));

  const revoked = await apiTokenRepo.revokeApiTokenIfActive(
    orgId,
    existing.id,
    toIsoTimestamp(new Date()),
  );

  if (revoked === null) {
    return requireFound(
      await apiTokenRepo.findApiTokenById(orgId, existing.id),
      "ApiToken",
      tokenId,
    );
  }

  await emit("api_token.revoked", {
    ...actorEnvelope(actor),
    tokenId: revoked.id,
    name: revoked.name,
    tokenUserId: revoked.userId,
    reason: "manual",
  });

  return revoked;
}

/**
 * Resolves a presented secret to the `Actor` it acts as, or `null` when the
 * token cannot be used right now. A `read` token acts as a viewer; a `write`
 * token acts with the owner's role as it stands at this call. Only a successful
 * call touches the row (`lastUsedAt`).
 */
export async function authenticateApiToken(token: string): Promise<Actor | null> {
  const apiToken = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (apiToken === null) return null;

  const now = new Date();
  if (apiToken.revokedAt !== null) return null;
  if (new Date(apiToken.expiresAt).getTime() <= now.getTime()) return null;

  const org = await orgRepo.findOrgById(apiToken.orgId);
  if (org === null || org.archivedAt !== null) return null;

  const member = await memberRepo.findMember(apiToken.orgId, apiToken.userId);
  if (member === null || member.status !== "active") return null;

  await apiTokenRepo.touchApiTokenLastUsed(
    apiToken.orgId,
    apiToken.id,
    toIsoTimestamp(now),
  );

  return {
    userId: apiToken.userId,
    orgId: apiToken.orgId,
    role: apiToken.scope === "read" ? "viewer" : member.role,
  };
}

/**
 * Revokes every unrevoked token a removed member holds in the org, expired
 * ones included, with the remover as the actor. Tokens already revoked keep
 * their `revokedAt` and are not audited again; other orgs are untouched.
 */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    const tokens = await apiTokenRepo.listUnrevokedApiTokensForUser(
      payload.orgId,
      payload.userId,
    );

    for (const token of tokens) {
      const revoked = await apiTokenRepo.revokeApiTokenIfActive(
        payload.orgId,
        token.id,
        toIsoTimestamp(new Date()),
      );
      if (revoked === null) continue;

      await emit("api_token.revoked", {
        ...envelope(payload.orgId, payload.actorId),
        tokenId: revoked.id,
        name: revoked.name,
        tokenUserId: revoked.userId,
        reason: "member_removed",
      });
    }
  });
}

