import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { ZodError } from "zod";
import { hashToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { listActivity } from "@/server/services/activity-service";
import {
  authenticateApiToken,
  createApiToken,
  listApiTokens,
  revokeApiToken,
} from "@/server/services/api-token-service";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import { NotFoundError } from "@/server/services/_support";
import { removeMember, updateMemberRole } from "@/server/services/member-service";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Actor } from "@/types/member";

const DAY = 24 * 60 * 60 * 1000;
let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

async function auditRows(actor: Actor, action: "api_token.created" | "api_token.revoked") {
  const page = await listActivity(actor, {
    orgId: actor.orgId,
    action: [action],
    limit: 100,
    cursor: null,
  });
  return page.items;
}

describe("api tokens (scratch)", () => {
  let tenant: Tenant;

  beforeAll(async () => {
    tenant = await createTenant("tokens");
  });

  it("mints a read token for a viewer with prefix, expiry, and a secret-free audit row", async () => {
    const { token, apiToken } = await createApiToken(tenant.actors.viewer, {
      orgId: tenant.org.id,
      name: "  nightly  ",
      scope: "read",
      expiresInDays: 30,
    });
    expect(token).toMatch(/^tfk_[A-Za-z0-9_-]+$/);
    expect(apiToken.prefix).toBe(token.slice(0, 12));
    expect(apiToken.name).toBe("nightly");
    expect(apiToken.userId).toBe(tenant.userIds.viewer);
    expect(Date.parse(apiToken.expiresAt) - Date.parse(apiToken.createdAt)).toBe(30 * DAY);
    expect(apiToken.lastUsedAt).toBeNull();
    expect(apiToken.revokedAt).toBeNull();
    expect(Object.keys(apiToken).sort()).toEqual(
      ["createdAt", "expiresAt", "id", "lastUsedAt", "name", "orgId", "prefix", "revokedAt", "scope", "userId"],
    );

    const rows = (await auditRows(tenant.actors.owner, "api_token.created")).filter(
      (r) => r.subjectId === apiToken.id,
    );
    expect(rows).toHaveLength(1);
    expect(rows[0]).toMatchObject({
      actorId: tenant.userIds.viewer,
      subjectKind: "api_token",
      subjectId: apiToken.id,
    });
    expect(JSON.stringify(rows)).not.toContain(token);
    expect(JSON.stringify(rows)).not.toContain(hashToken(token));
  });

  it("refuses a write token to a viewer and stores nothing", async () => {
    const before = await listApiTokens(tenant.actors.viewer, tenant.org.id);
    await expect(
      createApiToken(tenant.actors.viewer, {
        orgId: tenant.org.id,
        name: "w",
        scope: "write",
        expiresInDays: 7,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(await listApiTokens(tenant.actors.viewer, tenant.org.id)).toHaveLength(before.length);
  });

  it("rejects invalid input with ZodError and a foreign orgId with the tenant-scope error", async () => {
    const ok = { orgId: tenant.org.id, name: "x", scope: "read" as const, expiresInDays: 1 };
    await expect(createApiToken(tenant.actors.member, { ...ok, name: "   " })).rejects.toBeInstanceOf(ZodError);
    await expect(createApiToken(tenant.actors.member, { ...ok, expiresInDays: 366 })).rejects.toBeInstanceOf(ZodError);
    await expect(createApiToken(tenant.actors.member, { ...ok, expiresInDays: 0 })).rejects.toBeInstanceOf(ZodError);
    const other = await createTenant("tokens-other");
    await expect(
      createApiToken(tenant.actors.member, { ...ok, orgId: other.org.id }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    expect(await listApiTokens(tenant.actors.member, tenant.org.id)).toHaveLength(0);
  });

  it("caps usable tokens at five per user per org; revoked and expired ones do not count", async () => {
    const capped = await createTenant("tokens-cap");
    const input = { orgId: capped.org.id, name: "cap", scope: "read" as const, expiresInDays: 1 };
    vi.useFakeTimers({ toFake: ["Date"] });
    try {
      vi.setSystemTime(new Date("2030-01-01T00:00:00.000Z"));
      const first = await createApiToken(capped.actors.member, input);
      for (let i = 1; i < 5; i += 1) await createApiToken(capped.actors.member, input);
      await expect(createApiToken(capped.actors.member, input)).rejects.toThrow();
      expect(await listApiTokens(capped.actors.member, capped.org.id)).toHaveLength(5);

      await createApiToken(capped.actors.admin, input);

      await revokeApiToken(capped.actors.member, capped.org.id, first.apiToken.id);
      await createApiToken(capped.actors.member, input);
      await expect(createApiToken(capped.actors.member, input)).rejects.toThrow();

      vi.setSystemTime(new Date("2030-01-02T00:00:00.000Z"));
      await createApiToken(capped.actors.member, input);
    } finally {
      vi.useRealTimers();
    }
  });

  it("lists own tokens newest first, including revoked; others' lists need admin", async () => {
    const a = await createApiToken(tenant.actors.member, {
      orgId: tenant.org.id, name: "a", scope: "read", expiresInDays: 2,
    });
    const b = await createApiToken(tenant.actors.member, {
      orgId: tenant.org.id, name: "b", scope: "read", expiresInDays: 2,
    });
    await revokeApiToken(tenant.actors.member, tenant.org.id, a.apiToken.id);
    const list = await listApiTokens(tenant.actors.member, tenant.org.id);
    const ids = list.map((t) => t.id);
    expect(ids.indexOf(b.apiToken.id)).toBeLessThan(ids.indexOf(a.apiToken.id));
    expect(list.find((t) => t.id === a.apiToken.id)?.revokedAt).not.toBeNull();

    await expect(
      listApiTokens(tenant.actors.member, tenant.org.id, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(
      await listApiTokens(tenant.actors.admin, tenant.org.id, tenant.userIds.member),
    ).toHaveLength(ids.length);
    await expect(listApiTokens(tenant.actors.owner, (await createTenant("tokens-x")).org.id)).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("revokes own token, makes repeats a no-op, requires admin for others, and audits the actor", async () => {
    const { apiToken } = await createApiToken(tenant.actors.member, {
      orgId: tenant.org.id, name: "rev", scope: "write", expiresInDays: 5,
    });
    await expect(revokeApiToken(tenant.actors.viewer, tenant.org.id, apiToken.id)).rejects.toBeInstanceOf(PermissionDeniedError);

    const first = await revokeApiToken(tenant.actors.member, tenant.org.id, apiToken.id);
    expect(first.revokedAt).not.toBeNull();
    const again = await revokeApiToken(tenant.actors.member, tenant.org.id, apiToken.id);
    expect(again.revokedAt).toBe(first.revokedAt);
    const rows = (await auditRows(tenant.actors.owner, "api_token.revoked")).filter((r) => r.subjectId === apiToken.id);
    expect(rows).toHaveLength(1);
    expect(rows[0]?.actorId).toBe(tenant.userIds.member);

    const second = await createApiToken(tenant.actors.member, {
      orgId: tenant.org.id, name: "by-admin", scope: "read", expiresInDays: 5,
    });
    await revokeApiToken(tenant.actors.admin, tenant.org.id, second.apiToken.id);
    const adminRows = (await auditRows(tenant.actors.owner, "api_token.revoked")).filter((r) => r.subjectId === second.apiToken.id);
    expect(adminRows).toHaveLength(1);
    expect(adminRows[0]?.actorId).toBe(tenant.userIds.admin);

    await expect(revokeApiToken(tenant.actors.owner, tenant.org.id, "01HZZZNOPENOPENOPENOPENOPE")).rejects.toBeInstanceOf(NotFoundError);
  });

  it("authenticates read as viewer and write at the owner's current role; failures leave lastUsedAt alone", async () => {
    const auth = await createTenant("tokens-auth");
    const read = await createApiToken(auth.actors.member, { orgId: auth.org.id, name: "r", scope: "read", expiresInDays: 3 });
    const write = await createApiToken(auth.actors.member, { orgId: auth.org.id, name: "w", scope: "write", expiresInDays: 3 });

    expect(await authenticateApiToken(read.token)).toEqual({ userId: auth.userIds.member, orgId: auth.org.id, role: "viewer" });
    expect(await authenticateApiToken(write.token)).toEqual({ userId: auth.userIds.member, orgId: auth.org.id, role: "member" });

    const memberRow = await memberRepo.findMember(auth.org.id, auth.userIds.member);
    if (!memberRow) throw new Error("member missing");
    await updateMemberRole(auth.actors.owner, { orgId: auth.org.id, memberId: memberRow.id, role: "admin" });
    expect(await authenticateApiToken(write.token)).toEqual({ userId: auth.userIds.member, orgId: auth.org.id, role: "admin" });

    expect(await authenticateApiToken("tfk_unknown-token-value")).toBeNull();
    const seen = (await listApiTokens(auth.actors.member, auth.org.id)).find((t) => t.id === read.apiToken.id);
    expect(seen?.lastUsedAt).not.toBeNull();
  });

  it("stops at exactly expiresAt, after revocation, and when the org is archived", async () => {
    const t = await createTenant("tokens-expiry");
    vi.useFakeTimers({ toFake: ["Date"] });
    try {
      vi.setSystemTime(new Date("2031-03-01T12:00:00.000Z"));
      const { token, apiToken } = await createApiToken(t.actors.member, {
        orgId: t.org.id, name: "e", scope: "read", expiresInDays: 1,
      });
      vi.setSystemTime(new Date(Date.parse(apiToken.expiresAt) - 1));
      expect(await authenticateApiToken(token)).not.toBeNull();
      vi.setSystemTime(new Date(Date.parse(apiToken.expiresAt)));
      expect(await authenticateApiToken(token)).toBeNull();
    } finally {
      vi.useRealTimers();
    }

    const revoked = await createApiToken(t.actors.member, { orgId: t.org.id, name: "rv", scope: "read", expiresInDays: 3 });
    await revokeApiToken(t.actors.member, t.org.id, revoked.apiToken.id);
    expect(await authenticateApiToken(revoked.token)).toBeNull();

    const archived = await createApiToken(t.actors.member, { orgId: t.org.id, name: "ar", scope: "read", expiresInDays: 3 });
    await orgRepo.archiveOrg(t.org.id);
    expect(await authenticateApiToken(archived.token)).toBeNull();
  });

  it("revokes a removed member's unrevoked tokens in this org only, including expired ones, audited with the remover", async () => {
    const r = await createTenant("tokens-removal");
    const elsewhere = await createTenant("tokens-else");
    await memberRepo.insertMember(elsewhere.org.id, r.userIds.member, "member", null);
    const elsewhereActor: Actor = { userId: r.userIds.member, orgId: elsewhere.org.id, role: "member" };

    vi.useFakeTimers({ toFake: ["Date"] });
    try {
      vi.setSystemTime(new Date("2032-01-01T00:00:00.000Z"));
      const expiring = await createApiToken(r.actors.member, { orgId: r.org.id, name: "exp", scope: "read", expiresInDays: 1 });
      const active = await createApiToken(r.actors.member, { orgId: r.org.id, name: "act", scope: "write", expiresInDays: 30 });
      const preRevoked = await createApiToken(r.actors.member, { orgId: r.org.id, name: "pre", scope: "read", expiresInDays: 30 });
      const preRevokedAt = (await revokeApiToken(r.actors.member, r.org.id, preRevoked.apiToken.id)).revokedAt;
      const elsewhereToken = await createApiToken(elsewhereActor, { orgId: elsewhere.org.id, name: "else", scope: "read", expiresInDays: 30 });

      vi.setSystemTime(new Date("2032-01-05T00:00:00.000Z"));
      const memberRow = await memberRepo.findMember(r.org.id, r.userIds.member);
      if (!memberRow) throw new Error("member missing");
      await removeMember(r.actors.admin, { orgId: r.org.id, memberId: memberRow.id });

      const mine = await listApiTokens(r.actors.admin, r.org.id, r.userIds.member);
      const byId = new Map(mine.map((t) => [t.id, t]));
      expect(byId.get(expiring.apiToken.id)?.revokedAt).not.toBeNull();
      expect(byId.get(active.apiToken.id)?.revokedAt).toBe("2032-01-05T00:00:00.000Z");
      expect(byId.get(preRevoked.apiToken.id)?.revokedAt).toBe(preRevokedAt);

      const removalRows = (await auditRows(r.actors.owner, "api_token.revoked")).filter(
        (row) => row.subjectId === expiring.apiToken.id || row.subjectId === active.apiToken.id,
      );
      expect(removalRows).toHaveLength(2);
      for (const row of removalRows) expect(row.actorId).toBe(r.userIds.admin);
      const preRows = (await auditRows(r.actors.owner, "api_token.revoked")).filter((row) => row.subjectId === preRevoked.apiToken.id);
      expect(preRows).toHaveLength(1);

      expect(await authenticateApiToken(active.token)).toBeNull();
      expect(await authenticateApiToken(elsewhereToken.token)).not.toBeNull();
    } finally {
      vi.useRealTimers();
    }
  });
});

